// Concurrent TCP server using fork()
// Each client gets its own child process

while (1) {
    // Accept new client connection
    connfd = accept(listenfd, (struct sockaddr*)&cliaddr, &clilen);
    if (connfd < 0) {
        if (errno == EINTR) continue;  // Interrupted by signal, retry
        perror("accept"); break;
    }

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        close(connfd);
        continue;
    }

    if (pid == 0) {
        // CHILD: handle this client
        close(listenfd);  // Child does not need the listening socket

        serve_client(connfd);  // Exchange data with client

        close(connfd);
        exit(0);  // Child exits when done

    } else {
        // PARENT: go back to accepting
        close(connfd);  // Parent gives up this connection (child owns it)
        // Reap zombie children (simplified)
        waitpid(-1, NULL, WNOHANG);
    }
}

#include <sys/select.h>
#include <sys/socket.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

void run_select_server(int listenfd) {
    fd_set master_set, working_set;
    int maxfd = listenfd;
    char buf[1024];

    FD_ZERO(&master_set);
    FD_SET(listenfd, &master_set);  // Watch the listening socket

    while (1) {
        // Copy master to working (select() will modify working)
        working_set = master_set;

        // Block until at least one fd is ready
        int ready = select(maxfd + 1, &working_set, NULL, NULL, NULL);
        if (ready < 0) { perror("select"); break; }

        // Check all fds from 0 to maxfd
        for (int fd = 0; fd <= maxfd; fd++) {
            if (!FD_ISSET(fd, &working_set)) continue;  // Not ready

            if (fd == listenfd) {
                // New connection arriving
                int connfd = accept(listenfd, NULL, NULL);
                FD_SET(connfd, &master_set);  // Add client to set
                if (connfd > maxfd) maxfd = connfd;
                printf("New client: fd=%d\n", connfd);

            } else {
                // Existing client has data (or disconnected)
                int n = read(fd, buf, sizeof(buf) - 1);
                if (n <= 0) {
                    // n==0: client closed; n<0: error
                    printf("Client fd=%d disconnected\n", fd);
                    close(fd);
                    FD_CLR(fd, &master_set);  // Remove from set
                } else {
                    buf[n] = '\0';
                    // Echo back
                    write(fd, buf, n);
                }
            }
        }
    }
}

// UDP Echo Server
#include <sys/socket.h>
#include <netinet/in.h>
#include <stdio.h>
#include <string.h>

#define PORT 9000

int main() {
    int sockfd;
    struct sockaddr_in servaddr, cliaddr;
    char buf[1024];
    socklen_t clilen = sizeof(cliaddr);

    // Create UDP socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);

    // Bind to port
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;
    servaddr.sin_port = htons(PORT);
    bind(sockfd, (struct sockaddr*)&servaddr, sizeof(servaddr));

    printf("UDP server listening on port %d\n", PORT);

    while (1) {
        // Block until datagram arrives, learn who sent it
        int n = recvfrom(sockfd, buf, sizeof(buf)-1, 0,
                         (struct sockaddr*)&cliaddr, &clilen);
        buf[n] = '\0';
        printf("Received: %s\n", buf);

        // Send the datagram BACK to the same sender
        sendto(sockfd, buf, n, 0,
               (struct sockaddr*)&cliaddr, clilen);
    }
    return 0;
}
